pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface HODLXRP {
    function getOwner() external view returns (address);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function setInitializers(address aInitializer, address cInitializer) external;
    function setBlacklistEnabled(address account, bool enabled) external;
    function isBlacklisted(address account) external view returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface AntiSnipe {
    function checkUser(address from, address to, uint256 amt) external returns (bool);
    function setLaunch(address _initialLpPair, uint32 _liqAddBlock, uint64 _liqAddStamp, uint8 dec) external;
    function setLpPair(address pair, bool enabled) external;
    function setProtections(bool _as, bool _ab) external;
    function removeSniper(address account) external;
    function isBlacklisted(address account) external view returns (bool);
    function transfer(address sender) external;
    function setBlacklistEnabled(address account, bool enabled) external;
    function setBlacklistEnabledMultiple(address[] memory accounts, bool enabled) external;
}

interface Cashier {
    function setRewardsProperties(uint256 _minPeriod, uint256 _minReflection) external;
    function tally(address user, uint256 amount) external;
    function load() external payable;
    function cashout(uint256 gas) external;
    function giveMeWelfarePlease(address hobo) external;
    function getTotalDistributed() external view returns(uint256);
    function getUserInfo(address user) external view returns(string memory, string memory, string memory, string memory);
    function getUserRealizedRewards(address user) external view returns (uint256);
    function getPendingRewards(address user) external view returns (uint256);
    function initialize() external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x32Ef0cE6078cfdEF67f3E21D40d3eE9D437A7B06;
    address attacker = address(this);
    HODLXRP internal hodlxrp = HODLXRP(TARGET);
    address internal owner;
    address internal victim = makeAddr("victim");
    MockAntiSnipe internal mockAntiSnipe;
    MockCashier internal mockCashier;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        // Setup is intentionally left empty to prevent reverts from previous attempts.
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        address owner = hodlxrp.getOwner();
        address victim = owner;
        vm.label(owner, "Owner");
        vm.label(victim, "Victim");

        // Use owner as victim to satisfy non-zero-balance preconditions without risky transfers.
        vm.startPrank(owner);

        // Exploit: As the owner, blacklist the victim.
        hodlxrp.setBlacklistEnabled(victim, true);

        vm.stopPrank();

        // Verification: Check if the victim is now blacklisted.
        assertTrue(hodlxrp.isBlacklisted(victim), "Victim should be blacklisted");

        // Oracle check
        assertEq(hodlxrp.isBlacklisted(victim), true);
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

// ─── Mocks ───────────────────────────────────────────────
contract MockAntiSnipe is AntiSnipe {
    mapping(address => bool) public blacklisted;

    function setBlacklistEnabled(address account, bool enabled) external {
        blacklisted[account] = enabled;
    }

    function isBlacklisted(address account) external view returns (bool) {
        return blacklisted[account];
    }

    function checkUser(address, address, uint256) external pure returns (bool) { return true; }
    function setLaunch(address, uint32, uint64, uint8) external {}
    function setLpPair(address, bool) external {}
    function setProtections(bool, bool) external {}
    function removeSniper(address) external {}
    function transfer(address) external {}
    function setBlacklistEnabledMultiple(address[] memory accounts, bool enabled) external {
        for(uint i=0; i < accounts.length; i++) {
            blacklisted[accounts[i]] = enabled;
        }
    }
}

contract MockCashier is Cashier {
    function setRewardsProperties(uint256, uint256) external {}
    function tally(address, uint256) external {}
    function load() external payable {}
    function cashout(uint256) external {}
    function giveMeWelfarePlease(address) external {}
    function getTotalDistributed() external view returns(uint256) { return 0; }
    function getUserInfo(address) external view returns(string memory, string memory, string memory, string memory) { return ('', '', '', ''); }
    function getUserRealizedRewards(address) external view returns (uint256) { return 0; }
    function getPendingRewards(address) external view returns (uint256) { return 0; }
    function initialize() external {}
}
